:root {
  /* 斜体文本 */
  --SmartThemeEmColor: #505050;              /* ✏️【斜体色】灰黑色 */
  /* 下划线文本 */
  --SmartThemeUnderlineColor: rgba(125, 125, 125, 1);       /* ✏️【下划线色】中灰色 */
  /* 阴影颜色 */
  --SmartThemeShadowColor: rgba(176, 176, 176, 0.2); /* ✏️【阴影色】半透明黑 */
  /* 聊天背景 */
  --SmartThemeChatTintColor: #FFFFFF;        /* ✏️【聊天背景】白色 */
  /* UI背景 */
  --SmartThemeBlurTintColor: #F5F5F5;        /* ✏️【UI背景】浅灰 */
  /* 用户模糊色调 */
  --SmartThemeUserMesBlurTintColor: rgba(255, 255, 255, 0.9);
  /* AI模糊色调 */
  --SmartThemeBotMesBlurTintColor: rgba(255, 255, 255, 0.9);
}

body {
  font-family: , sans-serif !important;
  font-weight: normal;
  background-color: #FFFFFF !important;
  color: var(--SmartThemeBodyColor) !important;
}

#top-settings-holder {
  background: #FFFFFF !important;
  border-bottom: 1px solid #1E1E1E !important;  /* ✏️【顶栏边框】 */
}

#chat { background: transparent !important; }


/* =========================================
   🚩 气泡设置：【开始】统一拉伸版
   ========================================= */

/* 1. 基础布局容器 (mes) */
.mes {
  position: relative !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;

  /* ✨ 固定355px宽度 */
  width: 355px !important;
  max-width: 355px !important;
  /* ✏️【整体上下位置】可能需要微调 */
  margin: 280px auto 100px !important; 

  /* 背景三段式 - 垂直平铺 + 固定宽度 + 自动高度 */
background: url("https://i.postimg.cc/4yJ2sDnw/无标题463_20260401164130.png") repeat-y !important;
background-size: 100% auto !important;   /* 宽度100%填满容器，高度自动 */
background-repeat: repeat-y !important;
background-position: top center !important;
background-color: transparent !important;
border: none !important;
box-shadow: none !important;
overflow: visible !important;

  /* 布局间距控制 */
  gap: 15px;
}

/* 2. 背景伪元素 (三段式切图：顶 & 底) */
.mes::before {
  content: "" !important;
  position: absolute !important;
  top: -247px !important;                 /* ✏️【上下位置】可调 */
  left: 0 !important;                      /* ✏️【左右位置】可调 */
  width: 100% !important;
  height: 247px !important;                /* ✏️【高度】可调 */
  background: url("https://i.postimg.cc/zGFmWYRX/wu-biao-ti463-20260401165624.png") no-repeat center bottom !important;
  /* 【关键修改】从 100% 100% 改为 contain，保持原比例不拉伸 */
  background-size: contain !important;
  background-position: center bottom !important;
  z-index: -1 !important;
}

.mes::after {
  content: "" !important;
  position: absolute !important;
  bottom: -110px !important;                /* ✏️底图位置，保持原样 */
  left: 0 !important;
  width: 100% !important;
  height: 110px !important;                 /* ✏️底图高度，保持原样 */
  background: url("https://i.postimg.cc/hGn2LJqj/wu-biao-ti463-20260401171813.png") no-repeat center top !important;
  background-size: contain !important;     /* 关键修改：从 100% 100% 改为 contain，保持原比例不拉伸 */
  z-index: -1 !important;
}

/* 3. 头像与三元素容器 */
.mes .mesAvatarWrapper {
  position: absolute !important;
  top: -230px !important; 
  left: 35% !important;
  transform: translateX(-50%) !important;
  z-index: 2 !important;

  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
  background: none !important;
  padding: 0 !important;
}

/* 4. 文本块布局  */
.mes_block {
    display: flex !important;
    flex-direction: column !important;

    /* 核心修改：让文字块宽度超过100%并向右强制拉伸 */
    width: calc(100% + 10px) !important;  /* ✏️【宽度拉伸】数值越大越往右突 */
    margin-left: 0 !important;
    margin-right: -10px !important;       /* ✏️【右突力度】负值越大越往右突 */
    margin-top: -70px !important;          /* ✏️【上移距离】负值越大越往上 */

    /* 内边距：控制文字距离背景边缘的真实距离 */
    padding: 15px 20px 15px 20px !important;      /* ✏️【文字边距】 */

    box-sizing: border-box !important;
    z-index: 1 !important;
    overflow: visible !important;
}

/* 5. 文字排版细节优化 */
.mes_text {
  color: var(--SmartThemeBodyColor) !important;
  line-height: 1.8 !important;
  word-wrap: break-word !important;
  text-align: justify !important;       /* ✏️【对齐方式】justify=两端对齐 */
  padding-right: 15px !important;       /* ✏️【文字右边距】防止文字贴边 */
}

/* =========================================
   🚩 头像设置
   ========================================= */

/* 先清除所有可能的干扰 */
.mes .avatar,
.mesAvatarWrapper .avatar,
.mes .mesAvatarWrapper .avatar {
    all: initial !important;
    display: block !important;
    /* ✏️【宽度】数字越大越宽 */
    width: 133px !important;
    /* ✏️【高度】数字越大越高 */
    height: 80px !important;
    /* ✏️【圆角】数字越大越圆 */
    border-radius: 0px !important;
    overflow: hidden !important;
    position: relative !important;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: none !important;
    background-color: transparent !important;
    background-image: none !important;
    /* ✏️【头像旋转】只影响头像，不影响头像框 */
    transform: rotate(1.5deg) !important;
}

/* 头像图片 */
.mes .avatar img,
.mesAvatarWrapper .avatar img,
.mes .mesAvatarWrapper .avatar img {
    all: initial !important;
    display: block !important;
    width: 100% !important;
    height: 100% !important;
    object-fit: cover !important;
    object-position: center !important;
    border: none !important;
    outline: none !important;
    box-shadow: none !important;
    background: transparent !important;
}

/* 头像容器外层 - 不旋转 */
.mes .mesAvatarWrapper {
    position: absolute !important;
    /* ✏️【左右位置】数字越大越靠右，越小越靠左 */
    left: 36.5% !important;
    /* ✏️【上下位置】负数往上移，正数往下移 */
    top: -136px !important;
    transform: translateX(-50%) !important;
    z-index: 2 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    background: none !important;
    padding: 0 !important;
}

/* ===== 去除顶栏底部阴影和边框（保持背景纯净）===== */
#top-settings-holder,
#top-bar,
.drawer,
.drawer-header,
.drawer-icon {
  box-shadow: none !important;
  -webkit-box-shadow: none !important;
  -moz-box-shadow: none !important;
